  ['ellipse bottom', {x:0,y:0,w:200,h:100}, {x:100,y:300}, {x:100,y:100}],
];
for (const [name, box, from, want] of cases) {
  const got = ellipseBindingPoint(box, from);
  console.log(name, got, want, Math.abs(got.x-want.x)<1e-9 && Math.abs(got.y-want.y)<1e-9 ? 'OK' : 'FAIL');
